async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const mutating = init?.method && !['GET', 'HEAD'].includes(init.method);
  const response = await fetch(path, { credentials: 'same-origin', cache: 'no-store', ...init, body: mutating ? init?.body ?? '{}' : init?.body, headers: { ...(mutating ? { 'Content-Type': 'application/json' } : {}), ...init?.headers } });
  if (!response.ok) {
    if (response.status === 401 || response.status === 403) throw new Error('登入已過期或此帳號尚未受邀，請重新登入。');
    if (response.status === 502 || response.status === 503 || response.status === 504) throw new Error('目前無法連上家中的主機，主機恢復後即可繼續。');
    let description = '操作未完成，請稍後重試。';
    try { const body = await response.json(); if (typeof body.error === 'string') description = body.error; else if (typeof body.message === 'string') description = body.message; } catch { /* Response may be the edge offline page. */ }
    throw new Error(description);
  }
  if (response.status === 204) return undefined as T;
  const contentType = response.headers.get('content-type') || '';
  if (!contentType.includes('application/json')) throw new Error('登入狀態已變更，請重新載入頁面。');
  return response.json() as Promise<T>;
}
const errorText = (error: unknown) => error instanceof TypeError ? '目前無法連上主機，請確認網路連線或稍後重試。' : error instanceof Error ? error.message : '操作未完成，請稍後重試。';

function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) {
  return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div>;
}
function Modal({ title, eyebrow, children, close, wide = false }: { title: string; eyebrow?: string; children: ReactNode; close: () => void; wide?: boolean }) {
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const initial = panel.current?.querySelector<HTMLElement>('input') ?? panel.current?.querySelector<HTMLElement>('button, [tabindex="0"]'); initial?.focus();
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') close();
      if (event.key === 'Tab') {
        const nodes = panel.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), a[href], select, [tabindex="0"]');
        if (!nodes?.length) return;
        const first = nodes[0], last = nodes[nodes.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener('keydown', key); const old = document.body.style.overflow; document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', key); document.body.style.overflow = old; previous?.focus(); };
  }, [close]);
  return <div className="modal-backdrop" onClick={event => { if (event.target === event.currentTarget) close(); }}><div ref={panel} className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div><button className="icon-button" onClick={close} aria-label="關閉視窗"><X size={20} /></button></div>{children}</div></div>;
}
function PriceChange({ value, percent }: { value: number | null | undefined; percent?: number | null }) {
  return <span className={`price-change ${value == null || value === 0 ? 'neutral' : value > 0 ? 'up' : 'down'}`}>{value != null && value !== 0 && (value > 0 ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />)}{value == null ? '—' : `${value > 0 ? '+' : ''}${fmt(value)}`}{percent != null && <small> ({percent > 0 ? '+' : ''}{fmt(percent)}%)</small>}</span>;
}
function NewsList({ items, target }: { items: NewsItem[]; target: TranslationTarget }) {
  if (!items.length) return <Empty icon={<Newspaper size={25} />} title="還沒有相關消息">加入追蹤後會檢查相關新聞；目前沒有可取得的標題。</Empty>;
  return <div className="news-list">{items.slice(0, 12).map(item => <article key={item.id} className="news-entry"><a href={item.url} target="_blank" rel="noopener noreferrer" className="news-item"><div className="news-meta"><span className={item.kind === 'announcement' ? 'news-tag announcement' : 'news-tag'}>{item.kind === 'announcement' ? '公司公告' : item.source}</span><span>{item.datePrecision === 'day' ? item.publishedDate : localTime(item.publishedAt)}</span>{item.matchType === 'provider' && <span>來源關聯</span>}{item.paid && <span>原文可能需訂閱</span>}</div><h3>{item.title}<ArrowUpRight size={15} /></h3></a><div className="translation-links"><a href={translationLink(item.title,target)} target="_blank" rel="noopener noreferrer">翻譯標題 ↗</a><a href={translationLink(item.url,target,'website')} target="_blank" rel="noopener noreferrer">翻譯原文 ↗</a></div></article>)}</div>;
}
function HistoryChart({ history, range, security }: { history: HistoryResponse; range: Range; security?: Security }) {
  const rows = history.quotes.filter(row => row.close != null).sort((a, b) => a.date.localeCompare(b.date));
  const [hover, setHover] = useState<number | null>(null);
  useEffect(() => setHover(null), [range, history]);
  if (!rows.length) return <Empty icon={<TrendingUp size={26} />} title="走勢資料準備中">新加入的標的會在背景補抓歷史行情；若來源缺少資料，會顯示實際可取得的期間。</Empty>;
  const width = 620, height = 250, left = 5, right = 62, top = 22, base = 174;
  const closes = rows.map(row => row.close!); const min = Math.min(...closes), max = Math.max(...closes); const span = max - min || max * .04 || 1;
  const low = min - span * .14, high = max + span * .14;
  const x = (index: number) => rows.length === 1 ? (width - right + left) / 2 : left + index / (rows.length - 1) * (width - left - right);
  const y = (close: number) => top + (high - close) / (high - low) * (base - top);
  const line = rows.map((row, index) => `${index ? 'L' : 'M'}${x(index).toFixed(1)},${y(row.close!).toFixed(1)}`).join(' ');
  const highestVolume = Math.max(...rows.map(row => row.volume ?? 0), 1);
  const selected = hover == null ? null : rows[hover];
  return <div className="chart-wrap">{rows.some(row => row.qualityWarning) && <p className="inline-error" role="status">來源價格有大幅跳點，拆股調整或資料品質待核對。圖中保留原值，異常日不計算漲跌；請參考原始來源。</p>}<div className="chart-inspection" aria-live="polite">{selected ? <><span>{shortDate(selected.date)}</span><strong>{fmt(selected.close)} <small>{security?.currency ?? 'TWD'}</small></strong><span>成交量 {selected.volume == null ? '—' : `${selected.volumePrecision === 'thousand_shares' ? '約 ' : ''}${integer.format(selected.volume)} 股`}</span></> : <><span>日收盤價</span><span className="chart-hover-hint">移動游標查看當日價格</span></>}</div><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${rows[0].date} 到 ${rows[rows.length - 1].date} 的${security ? priceBasis(security.market) : '收盤價格'}，最低 ${fmt(min)}，最高 ${fmt(max)} ${security?.currency ?? ''}`} onMouseLeave={() => setHover(null)} onMouseMove={event => { const bounds = event.currentTarget.getBoundingClientRect(); const position = (event.clientX - bounds.left) / bounds.width * width; setHover(Math.max(0, Math.min(rows.length - 1, Math.round((position - left) / (width - left - right) * (rows.length - 1))))); }}>
    <defs><linearGradient id="price-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#52745e" stopOpacity=".17" /><stop offset="100%" stopColor="#52745e" stopOpacity="0" /></linearGradient></defs>
    {[0, 1, 2, 3].map(index => { const price = low + (high - low) * index / 3; return <g key={index}><line x1={left} x2={width - right} y1={y(price)} y2={y(price)} stroke="#e8ebe4" strokeDasharray="3 5" /><text x={width - right + 12} y={y(price) + 4} className="chart-axis">{money.format(price)}</text></g>; })}
    {rows.length > 1 && <path d={`${line} L${x(rows.length - 1)},${base} L${left},${base} Z`} fill="url(#price-fill)" />}<path d={line} fill="none" stroke="#54715c" strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round" />{rows.length === 1 && <circle cx={x(0)} cy={y(rows[0].close!)} r="4" fill="#54715c" />}
    {rows.map((row, index) => <rect key={row.date} x={x(index) - Math.max(1, Math.min(6, 220 / rows.length)) / 2} y={219 - (row.volume ?? 0) / highestVolume * 28} width={Math.max(1, Math.min(6, 220 / rows.length))} height={(row.volume ?? 0) / highestVolume * 28} fill={(row.change ?? 0) >= 0 ? '#c5d4c6' : '#e0cec5'} rx="1" />)}
    <text x={left} y="244" className="chart-axis">{shortDate(rows[0].date)}</text><text x={width - right} y="244" textAnchor="end" className="chart-axis">{shortDate(rows[rows.length - 1].date)}</text><text x={width - right + 12} y="213" className="chart-axis">成交量</text>
    {hover != null && <g><line x1={x(hover)} x2={x(hover)} y1={top} y2="224" stroke="#8c9d8c" strokeDasharray="3 4" /><circle cx={x(hover)} cy={y(rows[hover].close!)} r="4" fill="#3e5e48" stroke="#fff" strokeWidth="2" /></g>}
  </svg><div className="data-note"><span>{security ? priceBasis(security.market) : '日收盤價格'}・不含股息報酬</span>{history.coverage.partial && <span className="warning-text">僅顯示可取得期間</span>}</div><div className="chart-coverage">查詢區間：{range.replace('m',' 個月').replace('y',' 年')}；資料涵蓋 {shortDate(history.coverage.from)} — {shortDate(history.coverage.to)}</div>{rows.length === 1 && <p className="chart-coverage">目前只有 1 個交易日；歷史行情補抓後會接續顯示。</p>}{rows.some(row => row.volumePrecision === 'thousand_shares') && <p className="chart-coverage">歷史成交量以張數換算，原始精度為千股。</p>}</div>;
}

function SecurityPicker({ existing, close, save, remove, initialRegion }: { initialRegion: Region; existing: WatchlistEntry | null; close: () => void; save: (security: Security, held: boolean, interested: boolean, group: string) => Promise<void>; remove: (id: string) => Promise<void> }) {
  const [region, setRegion] = useState<Region>(existing ? regionOf(existing.security.market) : initialRegion);
  const [query, setQuery] = useState(''); const [results, setResults] = useState<Security[]>([]); const [security, setSecurity] = useState<Security | null>(existing?.security ?? null);
  const [held, setHeld] = useState(existing?.held ?? false), [interested, setInterested] = useState(existing?.interested ?? true), [group, setGroup] = useState(existing?.group ?? '');
  const [busy, setBusy] = useState(false), [searching, setSearching] = useState(false), [error, setError] = useState('');
  useEffect(() => {
    if (security) return;
    const controller = new AbortController(); setSearching(true); setResults([]); setError('');
    const timeout = window.setTimeout(() => { api<Security[]>(`/api/v1/finance/securities?region=${region}&q=${encodeURIComponent(query)}`, { signal: controller.signal }).then(setResults).catch(error => { if (!controller.signal.aborted) setError(errorText(error)); }).finally(() => { if (!controller.signal.aborted) setSearching(false); }); }, region === 'TW' ? 220 : 600);
    return () => { window.clearTimeout(timeout); controller.abort(); };
  }, [query, security, region]);
  const submit = async (deleting = false) => { if (!security) return; setBusy(true); setError(''); try { if (deleting) await remove(security.id); else await save(security, held, interested, group.trim()); close(); } catch (error) { setError(errorText(error)); } finally { setBusy(false); } };
  return <Modal title={existing ? '管理追蹤標的' : '把在意的標的，加進來'} eyebrow="YOUR WATCHLIST" close={close}>{!security ? <><div className="tabs market-tabs" aria-label="搜尋市場">{(['TW', 'US', 'JP'] as const).map(value => <button key={value} className={region === value ? 'active' : ''} aria-pressed={region === value} onClick={() => { setRegion(value); setQuery(''); setResults([]); setError(''); }}>{regionNames[value]}</button>)}</div><label className="search-input"><Search size={19} /><input aria-label="搜尋股票名稱或代號" autoComplete="off" placeholder={region === 'TW' ? '例如 2330、0050、台積電' : region === 'US' ? '例如 AAPL、SPY、Apple' : '例如 7203、1306、Toyota'} value={query} onChange={event => { setQuery(event.target.value); setError(''); }} />{searching && <LoaderCircle className="spin" size={17} />}</label><p className="input-help">{region === 'TW' ? '台灣上市、上櫃股票與 ETF。' : '搜尋股票或 ETF；國際行情由 Yahoo Finance 提供，名稱可能為英文。'}</p><div className="search-results">{results.map(result => <button key={result.id} className="search-result" onClick={() => setSecurity(result)}><span className="security-badge">{result.symbol.slice(0, 2)}</span><span className="search-result-name"><strong>{result.name}</strong><span>{result.symbol} · {marketNames[result.market]} · {result.assetType === 'etf' ? 'ETF' : '股票'}</span></span><Plus size={18} /></button>)}{!searching && !results.length && <Empty icon={<Search size={25} />} title={query ? '找不到這個標的' : region === 'TW' ? '股票目錄準備中' : '搜尋你關心的標的'}>{query ? '試試完整代號或英文名稱；僅呈現所選市場的股票及 ETF。' : region === 'TW' ? '首次同步完成後，即可搜尋上市、上櫃股票及 ETF。' : '輸入股票代號或名稱，開始搜尋。'}</Empty>}</div></> : <><div className="chosen-security"><span className="security-badge large">{security.symbol.slice(0, 2)}</span><div><h3>{security.name}</h3><p>{security.symbol} · {marketNames[security.market]} · {security.assetType === 'etf' ? 'ETF' : '股票'}</p></div>{!existing && <button className="text-button" onClick={() => setSecurity(null)}>重新選擇</button>}</div><fieldset className="tracking-options"><legend>我想如何關注這個標的</legend><label className={`tracking-option ${held ? 'selected' : ''}`}><input type="checkbox" checked={held} onChange={event => setHeld(event.target.checked)} /><Wallet size={19} /><span><strong>目前持有</strong><small>標記為自己的持股</small></span></label><label className={`tracking-option ${interested ? 'selected' : ''}`}><input type="checkbox" checked={interested} onChange={event => setInterested(event.target.checked)} /><Eye size={19} /><span><strong>感興趣</strong><small>持續留意，慢慢了解</small></span></label></fieldset><label className="form-field">自訂分組 <span>選填</span><input value={group} onChange={event => setGroup(event.target.value)} maxLength={40} placeholder="例如：長期觀察、科技、ETF" /></label><p className="input-help">持有標記及分組只有自己看得到。加入追蹤後才下載個股行情、財報與新聞，同一股票共用一次擷取。</p><div className="modal-actions">{existing && <button className="danger-text" disabled={busy} onClick={() => void submit(true)}>移除追蹤</button>}<button className="button primary" disabled={busy || (!held && !interested)} onClick={() => void submit()}>{busy ? <LoaderCircle className="spin" size={16} /> : <Check size={16} />}{existing ? '儲存設定' : '加入追蹤'}</button></div>{!held && !interested && <p className="input-help">請選擇至少一種關注方式。</p>}</>}{error && <p className="inline-error" role="alert">{error}</p>}</Modal>;
}

