    Promise.all([api<SecurityDetail>(`/api/v1/finance/securities/${encodeURIComponent(selectedId)}`, { signal: controller.signal }), api<HistoryResponse>(`/api/v1/finance/securities/${encodeURIComponent(selectedId)}/history?range=${range}`, { signal: controller.signal })]).then(([nextDetail, nextHistory]) => { setDetail(nextDetail); setHistory(nextHistory); }).catch(error => { if (!controller.signal.aborted) setDetailError(errorText(error)); }).finally(() => { if (!controller.signal.aborted) setDetailLoading(false); });
